346	export function Timeline({ analysis, self, help = false, fps: given }: { analysis: Analysis; self: string | null; help?: boolean; fps?: Map<number, string> }) {
347	  const t = useT();
348	  const age = useStore((s) => s.profile.age);
349	  const [unfolded, setUnfolded] = useState<Set<number>>(new Set());
350	  const [sharing, setSharing] = useState(false);
351	  // Corrections are keyed by each message's fingerprint (the same one the vault takes), so a
352	  // correction made here still shows when the chat is checked again or opened from the vault.
353	  const own = useFingerprints(given ? null : analysis);
354	  const fps = given ?? own;
355	  const corrections = useStore((s) => s.profile.corrections);
356	  const corrected = analysis.findings.flatMap((f) => {
357	    const c = f.severity > 0 && f.message.sender !== self ? corrections[fps.get(f.message.id) ?? ""] : undefined;
358	    return c ? [{ correction: c, text: f.message.text, f }] : [];
359	  });
360	  // One HelpNow per screen: under the first corrected message that asks for help, the rest point to it.
361	  const helpUnder = help ? undefined : corrected.find(({ correction, f }) => correctionHelp(correction, correctedView(f, correction).gated).help)?.f.message.id;
362	  const rows = useMemo(() => {
363	    const out: Row[] = [];
364	    let lastDay = "";
365	    let quiet: Finding[] = [];
366	    const flushQuiet = () => {
367	      if (!quiet.length) return;
368	      // Keep one line of context either side of an attack; fold longer quiet stretches.
369	      if (quiet.length <= 3 || unfolded.has(quiet[0]!.message.id)) quiet.forEach((f) => out.push({ kind: "msg", f }));
370	      else {
371	        out.push({ kind: "msg", f: quiet[0]! });
372	        out.push({ kind: "fold", count: quiet.length - 2, from: quiet[0]!.message.id });
373	        out.push({ kind: "msg", f: quiet.at(-1)! });
374	      }
375	      quiet = [];
376	    };
377	    for (const f of analysis.findings) {
378	      const day = f.message.at ? f.message.at.toLocaleDateString(locale(), { weekday: "short", day: "numeric", month: "short" }) : "";
