380	        flushQuiet();
381	        out.push({ kind: "day", label: day });
382	        lastDay = day;
383	      }
384	      const loud = f.severity > 0 && f.message.sender !== self;
385	      if (loud) {
386	        flushQuiet();
387	        out.push({ kind: "msg", f });
388	      } else quiet.push(f);
389	    }
390	    flushQuiet();
391	    return out;
392	  }, [analysis, self, unfolded]);
