394	  return (
395	    <section aria-labelledby="timeline" className="rounded-card border border-line bg-surface p-4 sm:p-6">
396	      <div className="flex items-center gap-2">
397	        <ChatsCircle size={22} weight="bold" className="text-glow" />
398	        <h2 id="timeline" className="font-display text-lg font-bold tracking-tight">
399	          {t.result.theChat}
