401	        <span className="ms-auto text-sm text-dim">{t.result.messages(analysis.findings.length)}</span>
402	      </div>
403	      <ol className="mt-4 grid gap-2">
404	        {rows.map((r, i) => {
405	          if (r.kind === "day")
406	            return (
407	              <li key={`d${i}`} className="py-2 text-center text-xs font-bold uppercase tracking-wider text-dim">
408	                {r.label}
409	              </li>
410	            );
411	          if (r.kind === "fold")
412	            return (
413	              <li key={`f${r.from}`} className="text-center">
414	                <button onClick={() => setUnfolded((u) => new Set(u).add(r.from))} className="min-h-10 rounded-full px-3 text-sm font-bold text-dim hover:bg-raised hover:text-ink">
415	                  {t.result.ordinary(r.count)}
