417	              </li>
418	            );
419	          return <Bubble key={r.f.message.id} f={r.f} mine={r.f.message.sender === self} fp={fps.get(r.f.message.id)} help={help || helpUnder !== undefined} helpHere={helpUnder === r.f.message.id} />;
420	        })}
421	      </ol>
422	      {corrected.length > 0 && (
423	        <div className="mt-5 flex flex-wrap items-center gap-x-4 gap-y-2 border-t border-line pt-4 text-sm">
424	          <p className="text-dim">{t.correct.shareCount(corrected.length)}</p>
425	          {/* The file stays with the child; 8 to 10 aren't offered it at all. */}
426	          {age !== "8" && (
427	            <button onClick={() => setSharing(true)} className="min-h-11 font-bold text-glow hover:underline">
428	              {t.correct.shareOpen}
429	            </button>
430	          )}
431	        </div>
432	      )}
433	      {sharing && age !== "8" && <ShareCorrections items={corrected} wordLists={analysis.layers.packs} onClose={() => setSharing(false)} />}
434	    </section>
435	  );
436	}
