const profileKey = (id: string) => (id === "default" ? LEGACY_KEY : `ward.profile.${id}`);

/** What the "Who's using Ward?" screen needs, readable before a profile is unlocked. */
export interface ProfileEntry {
  id: string;
  name: string;
